'use strict';
const https = require('https');

var _SP = "";
var SYSTEM_PROMPT = Buffer.from(_SP, 'base64').toString('utf8');
var _DIR = "";
var HARDCODED_DIRECTORY = JSON.parse(Buffer.from(_DIR, 'base64').toString('utf8'));

var INTENT_GROUPS = {
  food:      ['caterers','restaurants','small chops','nigerian snacks','suya spot','cakes & desert','cakes & desserts','foodstores & groceries'],
  hair:      ['hair stylists/braiders','wig vendors','hair care','gele stylists'],
  beauty:    ['makeup artists','microblading','skincare'],
  fashion:   ['fashion & accessories','ankara & traditional wears','fashion designers','jewelry'],
  events:    ['event planners','photography','djs','alaga','videography'],
  education: ['tutors','education consultancy'],
  legal:     ['solicitors','accountants'],
  faith:     ['churches','ministries'],
  home:      ['home & kitchen','cleaning services','transport','printing services'],
};

var INTENT_KEYWORDS = {
  food:      /caterer|catering|food|cook|meal|jollof|rice|suya|restaurant|bukka|kitchen|small.?chop|puff.?puff|chin.?chin|snack|cake|baker|grocery|groceries|foodstore|african.?store/i,
  hair:      /hair|braid|wig|locs|loc |weave|extension|gele|natural hair|hair stylist|hairdress/i,
  beauty:    /makeup|mua|glam|lash|brow|microblade|skin.?care|beauty studio|semi.?perm/i,
  fashion:   /fashion|cloth|outfit|dress|ankara|fabric|tailor|wear|jewel|accessory|accessories/i,
  events:    /event|wedding|birthday|party|decor|photograph|dj|mc|entertain|owambe|celebrat/i,
  education: /tutor|school|lesson|educat|study|exam|gcse|a.level|university/i,
  legal:     /solicitor|lawyer|legal|immigrat|visa|accountant|tax|financial/i,
  faith:     /church|pastor|ministry|gospel|worship|pray/i,
  home:      /cookware|kitchen|clean|transport|courier|deliver|print/i,
};

function getIntentGroup(query) {
  var lower = query.toLowerCase();
  for (var group in INTENT_KEYWORDS) {
    if (INTENT_KEYWORDS[group].test(lower)) return group;
  }
  return null;
}

function searchBusinessesByIntent(query, limit, directory, userCity, page) {
  limit = limit || 6;
  var intentGroup = getIntentGroup(query);
  var groupCats = intentGroup ? INTENT_GROUPS[intentGroup] : null;

  var ukCities = ['london','birmingham','manchester','leeds','bristol','sheffield','liverpool','nottingham','coventry','leicester','edinburgh','glasgow','cardiff','belfast','newcastle','brighton','reading','oxford','cambridge','southampton','portsmouth','wolverhampton','bradford','derby','exeter','hull','luton','peterborough','stoke','sunderland','basildon','laindon','kent','surrey','norwich','colchester','chelmsford','basingstoke','aldershot','southend','york','worcester','bath','bournemouth','maidstone','northampton','wakefield','sittingbourne','ipswich'];
  var queryLoc = null;
  var queryL = query.toLowerCase();
  ukCities.forEach(function(city) { if (queryL.indexOf(city) !== -1) queryLoc = city; });
  var proximityCity = queryLoc || (userCity ? userCity.toLowerCase().trim() : null);

  var regionGroups = {
    london:    ['london','essex','kent','surrey','hertfordshire','middlesex','croydon','romford','ilford','barking','stratford','brixton','peckham','woolwich','enfield','hackney','islington','lewisham','southwark','lambeth','greenwich','newham','walthamstow','tottenham','harrow','uxbridge','slough','watford','luton','basildon','laindon','southend','chelmsford','colchester','maidstone','tonbridge','folkestone','bexleyheath','erith','dartford','witham'],
    southeast: ['brighton','reading','oxford','southampton','portsmouth','guildford','worthing','hastings','eastbourne','basingstoke','aldershot','farnham','woking','winchester','hampshire','berkshire','wiltshire','chichester','crawley','horsham','aylesbury','high wycombe','milton keynes','camberley'],
    midlands:  ['birmingham','coventry','leicester','nottingham','derby','wolverhampton','walsall','dudley','solihull','stoke','northampton','worcester','hereford','shrewsbury','telford','stafford','lichfield','warwick','rugby','warwickshire'],
    northwest:  ['manchester','liverpool','leeds','sheffield','bradford','bolton','oldham','salford','stockport','wigan','blackpool','preston','blackburn','rochdale','wakefield','huddersfield','chester','warrington'],
    northeast:  ['newcastle','sunderland','middlesbrough','hull','york','harrogate','durham','darlington','gateshead'],
    southwest:  ['bristol','bath','exeter','plymouth','gloucester','taunton','torquay','cornwall','devon','somerset','bournemouth','poole','dorset','swindon'],
    east:       ['cambridge','norwich','ipswich','peterborough','bedford','hertford','stevenage','nottingham'],
    scotland:   ['glasgow','edinburgh','aberdeen','dundee','inverness','stirling'],
    wales:      ['cardiff','swansea','newport','wrexham'],
    nireland:   ['belfast','derry','lisburn'],
  };

  var adjacentRegions = {
    london:    ['southeast','east','midlands'],
    southeast: ['london','southwest','east'],
    midlands:  ['london','northwest','northeast','southwest','east','southeast'],
    northwest:  ['midlands','northeast','scotland','wales'],
    northeast:  ['midlands','northwest','scotland','east'],
    southwest:  ['midlands','southeast','wales'],
    east:       ['london','southeast','midlands','northeast'],
    wales:      ['midlands','southwest','northwest'],
    scotland:   ['northwest','northeast'],
    nireland:   ['scotland'],
  };

  function getUserRegion(city) {
    if (!city) return null;
    var c = city.toLowerCase();
    for (var reg in regionGroups) {
      if (regionGroups[reg].some(function(r){ return c.indexOf(r)!==-1||r.indexOf(c)!==-1; })) return reg;
    }
    return null;
  }

  function getBizRegion(b) {
    var loc = (b.loc||'').toLowerCase();
    for (var reg in regionGroups) {
      if (regionGroups[reg].some(function(r){ return loc.indexOf(r)!==-1; })) return reg;
    }
    return null;
  }

  var userRegion = getUserRegion(proximityCity);

  var keywordCatMap = [
    [/makeup.?artist|mua|glam artist/i, 'makeup artists'],
    [/hair.?stylist|hairdress|braider|braiding/i, null],
    [/wig.?vendor|wig.?seller|sell.*wig|buy.*wig/i, 'wig vendors'],
    [/gele.?stylist|auto.?gele/i, 'gele stylists'],
    [/microbla/i, 'microblading'],
    [/skincare|skin.?care/i, 'skincare'],
    [/caterer|catering/i, 'caterers'],
    [/restaurant|bukka|dining/i, 'restaurants'],
    [/small.?chop/i, 'small chops'],
    [/cake|baker|pastry/i, 'cakes & desserts'],
    [/suya/i, 'suya spot'],
    [/food.?store|grocery|groceries|african.?store/i, 'foodstores & groceries'],
    [/fashion.?design/i, 'fashion designers'],
    [/ankara|asooke/i, 'ankara & traditional wears'],
    [/photograph/i, 'photography'],
    [/event.?plan/i, 'event planners'],
    [/dj\b/i, 'djs'],
    [/solicitor|lawyer/i, 'solicitors'],
    [/accountant/i, 'accountants'],
    [/tutor/i, 'tutors'],
  ];

  var exactCat = null;
  for (var ki = 0; ki < keywordCatMap.length; ki++) {
    if (keywordCatMap[ki][0].test(queryL)) { exactCat = keywordCatMap[ki][1]; break; }
  }
  if (!exactCat) {
    var allCats = Object.values(INTENT_GROUPS).reduce(function(a,b){return a.concat(b);}, []);
    exactCat = allCats.find(function(c){ return queryL.indexOf(c) !== -1; }) || null;
  }
  if (exactCat) groupCats = exactCat ? [exactCat] : groupCats;

  var proximityTiers = {exact:50, region:20, adjacent:10, uk:0};

  function getProximityScore(b) {
    var locL=(b.loc||'').toLowerCase();
    if (proximityCity&&locL.indexOf(proximityCity)!==-1) return proximityTiers.exact;
    var br=getBizRegion(b);
    if (!br) return proximityTiers.uk;
    if (br===userRegion) return proximityTiers.region;
    if (userRegion&&adjacentRegions[userRegion]&&adjacentRegions[userRegion].indexOf(br)!==-1) return proximityTiers.adjacent;
    return proximityTiers.uk;
  }

  function scoreBiz(b) {
    var catL = (b.cat||'').toLowerCase();
    var kwStr = (b.keywords||[]).join(' ').toLowerCase();
    var score = 0;
    if (groupCats) {
      var inGroup = groupCats.some(function(gc){ return catL.indexOf(gc)!==-1||kwStr.indexOf(gc)!==-1; });
      if (!inGroup) return 0;
      score += 30;
    }
    score += getProximityScore(b);
    if (b.verified) score += 100;
    return score;
  }

  var scored = directory.map(function(b){
    return Object.assign({}, b, { score: scoreBiz(b) });
  }).filter(function(b){ return b.score > 0; })
    .sort(function(a,b){ return b.score - a.score; });

  var hasLocal = scored.some(function(b){
    var locL=(b.loc||'').toLowerCase();
    return proximityCity&&locL.indexOf(proximityCity)!==-1;
  });
  var hasRegional = userRegion && scored.some(function(b){ return getBizRegion(b)===userRegion; });

  var scope = hasLocal ? 'local' : (hasRegional ? 'regional' : 'uk');
  var city = queryLoc || proximityCity || null;
  var pageOffset = (typeof page === 'number' ? page : 0) * limit;
  return { results: scored.slice(pageOffset, pageOffset + limit), total: scored.length, scope: scope, city: city, intentGroup: intentGroup };
}

function searchBusinesses(query, limit, directory, userCity) {
  limit = limit || 6;
  return searchBusinessesByIntent(query, limit, directory, userCity, 0);
}

function formatBusinessContext(businesses, scope, city) {
  if (!businesses.length) return '';
  var bizData = businesses.map(function(b){
    return {slug:b.slug,name:b.name,cat:b.cat||'',loc:b.loc||'UK',desc:b.desc?b.desc.substring(0,100):'',verified:b.verified||false,wa:b.wa||''};
  });
  var scopeNote = '\n[SEARCH_SCOPE: Showing '+businesses.length+' results sorted by proximity to '+(city||'user')+'.]';
  return '\n\n<<<BIZ_JSON:'+JSON.stringify(bizData)+'>>>'+scopeNote;
}

async function getDirectory() {
  console.log('[chat] Directory: ' + HARDCODED_DIRECTORY.length + ' businesses');
  return HARDCODED_DIRECTORY;
}



exports.handler=async function(event){
  if(event.httpMethod==='OPTIONS'){return{statusCode:200,headers:{'Access-Control-Allow-Origin':'*','Content-Type':'application/json'},body:''};}
  try{
    var body=JSON.parse(event.body);
    var apiKey=process.env.OPENROUTER_API_KEY;
    if(!apiKey)return{statusCode:500,headers:{'Access-Control-Allow-Origin':'*','Content-Type':'application/json'},body:JSON.stringify({error:'OPENROUTER_API_KEY not set'})};
    var lastMessage=body.messages&&body.messages.length>0?body.messages[body.messages.length-1].content||'':'';
    var recentMessages=body.messages?body.messages.slice(-4):[];
    var userCity=(body.userCity||'').toLowerCase().trim();
    var searchPage=parseInt(body.searchPage||0,10)||0;
    var isShortGreeting=/^(hi|hello|hey|hiya|good morning|good afternoon|good evening|thanks|thank you|okay|ok|great|nice|cool|sure|yes|no|alright|perfect|wonderful|brilliant|lovely)\W*$/i.test(lastMessage.trim());
    var questionWords=/^(can|will|how|what|is|are|do|does|when|where|why|should|would|could|if |please|tell|help|show|list|give)\b/i;
    var bizKeywords=/find|looking for|recommend|where can i|know any|any good|near me|show me|list me|show all|in london|in manchester|in birmingham|in leeds|caterer|hairdress|barber|salon|makeup|mua|grocery|restaurant|bukka|solicitor|accountant|tutor|plumber|photographer|event plan|decorator|dj|cleaner|travel agent|fashion|seamstres/i;
    var isGenericQuestion=questionWords.test(lastMessage.trim());
    var isNounSearch=!questionWords.test(lastMessage.trim())&&lastMessage.trim().split(/\s+/).length<=6;
    var showMeAll=/^show\s+(me\s+)?(all\s+)?/i.test(lastMessage.trim());
    var shouldSearch=!isShortGreeting&&(!isGenericQuestion||showMeAll)&&(bizKeywords.test(lastMessage)||isNounSearch||showMeAll||(lastMessage.trim().split(/\s+/).length>=2&&lastMessage.trim().split(/\s+/).length<=8));
    var searchMsg=lastMessage.replace(/\bcaterer\b/gi,'caterers').replace(/\bphotographer\b/gi,'photographers').replace(/\bplanner\b/gi,'planners').replace(/\bhairdresser\b/gi,'hairdressers').replace(/\bsolicitor\b/gi,'solicitors').replace(/\baccountant\b/gi,'accountants').replace(/\btutor\b/gi,'tutors').replace(/\bwig vendor\b/gi,'wig vendors').replace(/\bgele stylist\b/gi,'gele stylists');
    var _isNounSearch=isNounSearch;var businessContext='';
    if(shouldSearch){
      var directory=await getDirectory();
      var searchLimit=6;
      var sr=searchBusinessesByIntent(searchMsg,searchLimit,directory,userCity,searchPage);
      if(sr.results.length===0){sr=searchBusinesses(searchMsg,searchLimit,directory,userCity);}
      if(isNounSearch&&sr.results.length>0){
        var qClean=lastMessage.toLowerCase().replace(/[^a-z0-9\s]/g,'').trim();
        var stopWords=['the','and','for','near','find','with','from'];
        var qWords=qClean.split(/\s+/).filter(function(w){return w.length>2&&stopWords.indexOf(w)===-1;});
        if(qWords.length>0){
          var nameMatches=sr.results.filter(function(b){
            var nameL=b.name.toLowerCase().replace(/[^a-z0-9\s]/g,'');
            var catL=(b.cat||'').toLowerCase();
            return qWords.some(function(w){return nameL.indexOf(w)!==-1||catL.indexOf(w)!==-1;});
          });
          if(nameMatches.length>0)sr.results=nameMatches;
          else if(isNounSearch&&sr.results.length>0)sr.results=[];
        }
      }
      if(sr.results.length>0)businessContext=formatBusinessContext(sr.results,sr.scope,sr.city);
    }
    var systemContent=SYSTEM_PROMPT+(businessContext||'');
    var messages=[{role:'system',content:systemContent}].concat(recentMessages);
    var requestBody={model:'openai/gpt-4o-mini',max_tokens:600,temperature:0.7,messages:messages};
    var responseText=await new Promise(function(resolve,reject){
      var postData=JSON.stringify(requestBody);
      var options={hostname:'openrouter.ai',path:'/api/v1/chat/completions',method:'POST',headers:{'Authorization':'Bearer '+apiKey,'Content-Type':'application/json','HTTP-Referer':'https://auntietobi.co.uk','X-Title':'Auntie Tobi','Content-Length':Buffer.byteLength(postData)}};
      var req=https.request(options,function(res){
        var data='';
        res.on('data',function(chunk){data+=chunk;});
        res.on('end',function(){resolve(data);});
      });
      req.on('error',reject);
      req.setTimeout(20000,function(){req.destroy();reject(new Error('Timeout'));});
      req.write(postData);
      req.end();
    });
    var parsed=JSON.parse(responseText);
    var reply=parsed.choices&&parsed.choices[0]&&parsed.choices[0].message?parsed.choices[0].message.content:'';
    if(!reply){return{statusCode:500,headers:{'Access-Control-Allow-Origin':'*','Content-Type':'application/json'},body:JSON.stringify({error:parsed.error&&parsed.error.message||'No reply'})};}
    reply=reply.replace(/\[SEARCH_SCOPE:[^\]]*\]/g,'').trim();
    reply=reply.replace(/\[SUGGESTIONS:[\s\S]*?\]/g,'').trim();
    reply=reply.replace(/\[OPTION_[A-E]:[\s\S]*?\]/g,'').trim();
    if(businessContext){reply=reply.replace(/\[SHOW_BIZ_CARDS\]/,'').replace(/IF YOU CANT FIND.*?SEARCH\)/gi,'').trim();reply=reply+'\n'+businessContext.trim();}
    return{statusCode:200,headers:{'Access-Control-Allow-Origin':'*','Content-Type':'application/json'},body:JSON.stringify({content:[{type:'text',text:reply}]})};
  }catch(err){
    console.log('Error:',err.message);
    return{statusCode:500,headers:{'Access-Control-Allow-Origin':'*','Content-Type':'application/json'},body:JSON.stringify({error:err.message})};
  }
};

